import { readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// shadcn's own components are regenerated by the CLI, so only our code is checked.
const SKIP = [path.join("src", "components", "ui")];

const RAW_COLORS = [
    /#[0-9a-fA-F]{3,8}\b/,
    /\b(?:oklch|rgba?|hsla?)\(/,
    /\b(?:bg|text|border|ring|outline|fill|stroke|decoration|shadow|from|via|to)-(?:white|black|(?:slate|gray|zinc|neutral|stone|red|orange|amber|yellow|lime|green|emerald|teal|cyan|sky|blue|indigo|violet|purple|fuchsia|pink|rose)-\d{2,3})\b/,
];

const listFiles = (dir: string): string[] =>
    readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
        const file = path.join(dir, entry.name);
        if (SKIP.includes(file)) return [];
        if (entry.isDirectory()) return listFiles(file);
        return file.endsWith(".tsx") ? [file] : [];
    });

describe("theme tokens", () => {
    it("components use theme variables instead of raw colors", () => {
        const offenders = listFiles("src").flatMap((file) =>
            readFileSync(file, "utf8")
                .split("\n")
                .flatMap((line, i) =>
                    RAW_COLORS.some((pattern) => pattern.test(line))
                        ? [`${file}:${i + 1}: ${line.trim()}`]
                        : []
                )
        );
        expect(offenders).toEqual([]);
    });
});
